---@class TouchEventDetectionUtils
local TouchEventDetectionUtils = Class("TouchEventDetectionUtils")

------------ import ------------
local KTool = CS.Engine.Lib.KTool
local Input = CS.UnityEngine.Input
local IsNull = IsNull
------------ import ------------

------------ definition ------------
local DEFAULT_PRESS_DETECTION_TIME = 0.5
local DEFAULT_SHOW_PRESS_DETECTION_TIME = 0.3
------------ definition ------------

function TouchEventDetectionUtils:__init(data)
    self.isTouchCharacter = false
    self:__initTouchListener(data)
    self:SetEnabled(true)
end

function TouchEventDetectionUtils:__delete()
    self.touchScreenCallBack = nil
    self.showPressCallback = nil
    self.pressCallback = nil
    self.clickCallback = nil
    self.touchEndCallback = nil
    self.isTouchCharacter = nil
    self.startTime = nil
    self.enabled = nil
end

function TouchEventDetectionUtils:__initTouchListener(data)
    data = data or {}
    if next(data) == nil then
        return
    end

    local touchScreenCallback = data.touchScreenCallback
    if touchScreenCallback then
        self:RegisterTouchScreenCallback(touchScreenCallback)
    end

    local showPressCallback = data.showPressCallback
    if showPressCallback then
        self:RegisterShowPressCallback(showPressCallback)
    end

    local pressCallback = data.pressCallback
    if pressCallback then
        self:RegisterPressCallback(pressCallback)
    end

    local clickCallback = data.clickCallback
    if clickCallback then
        self:RegisterClickCallback(clickCallback)
    end

    local touchEndCallback = data.touchEndCallback
    if touchEndCallback then
        self:RegisterTouchEndCallback(touchEndCallback)
