---Detection
---用于检测触摸事件方法
function TouchEventDetectionUtils:Detection()
    --- 正在监听的话 直接返回
    if not self:GetEnabled() then
        return
    end
    if KTool.IsMobile() then
        self:__DetectionMobile()
    else
        self:__DetectionMouse()
    end
end

---__DetectionMobile
---私有方法 用于检测手机 单点触摸事件
function TouchEventDetectionUtils:__DetectionMobile()
    if Input.touchCount <= 0 then
        return
    end
    if Input.touchCount == 1 then
        local touch = Input.touches[0]
        local TouchPhase = CS.UnityEngine.TouchPhase
        if not IsNull(touch) then
            local phase = touch.phase
            if phase == TouchPhase.Began then
                if not CS.UnityEngine.EventSystems.EventSystem.current:IsPointerOverGameObject(Input.touches[0].fingerId) then
                    self.startTime = os.clock()
                end
                if self.touchScreenCallback() then
                    self.isTouchCharacter = true
                    self.broadCastShowSign = false
                end
            elseif phase == TouchPhase.Stationary then
                if self.isTouchCharacter and not IsNull(self.startTime) then
                    if os.clock() - self.startTime >= DEFAULT_SHOW_PRESS_DETECTION_TIME then
                        if self.showPressCallback and not self.broadCastShowSign then
                            self.broadCastShowSign = true
                            self.showPressCallback(true)
                        end
                    end
                    if os.clock() - self.startTime >= DEFAULT_PRESS_DETECTION_TIME then
                        -- 长按
                        self.startTime = os.clock()
                        if self.pressCallback then
                            self.isTouchCharacter = false
                            self.startTime = nil
                            self.pressCallback()
                        end
                    end
                end
            elseif phase == TouchPhase.Ended then
                if not IsNull(self.startTime) then
                    if os.clock() - self.startTime < DEFAULT_SHOW_PRESS_DETECTION_TIME then
                        -- 点击
                        if self.clickCallback then
                            self.clickCallback()
                        end
                    end
                    if self.isTouchCharacter and os.clock() - self.startTime >= DEFAULT_SHOW_PRESS_DETECTION_TIME then
                        -- 长按失败
                        if self.showPressCallback then
                            self.showPressCallback(false)
                        end
                    end
                end
                self.touchEndCallback()
                self.isTouchCharacter = false
                self.startTime = nil
            elseif phase == TouchPhase.Canceled then
                self.touchEndCallback()
                self.isTouchCharacter = false
                self.startTime = nil
            end
        end
    end
end

---__DetectionMouse
---私有方法 用于检测鼠标触摸事件
function TouchEventDetectionUtils:__DetectionMouse()
    if Input.GetMouseButtonDown(0) then
        if not CS.UnityEngine.EventSystems.EventSystem.current:IsPointerOverGameObject() then
            self.startTime = os.clock()
        end
        if self.touchScreenCallback() then
            self.isTouchCharacter = true
            self.broadCastShowSign = false
        end
    elseif Input.GetMouseButton(0) then
        if self.isTouchCharacter and not IsNull(self.startTime) then
            if os.clock() - self.startTime >= DEFAULT_SHOW_PRESS_DETECTION_TIME then
                -- 长按提示
                if self.showPressCallback and not self.broadCastShowSign then
                    self.broadCastShowSign = true
                    self.showPressCallback(true)
                end
            end
            if os.clock() - self.startTime >= DEFAULT_PRESS_DETECTION_TIME then
                -- 长按
                self.startTime = os.clock()
                if self.pressCallback then
                    self.isTouchCharacter = false
                    self.startTime = nil
                    self.pressCallback()
                end
            end
        end
    elseif Input.GetMouseButtonUp(0) then
        if not IsNull(self.startTime) then
            if os.clock() - self.startTime < DEFAULT_SHOW_PRESS_DETECTION_TIME then
                -- 点击
                if self.clickCallback then
                    self.clickCallback()
                end
            end
            if self.isTouchCharacter and os.clock() - self.startTime >= DEFAULT_SHOW_PRESS_DETECTION_TIME then
                -- 长按失败
                if self.showPressCallback then
                    self.showPressCallback(false)
                end
            end
        end
        self.touchEndCallback()
        self.isTouchCharacter = false
        self.startTime = nil
    end
end

